// ═══ ORDERING COMPARISON ═══
Map<String, Integer> hashMap = new HashMap<>();
Map<String, Integer> linkedMap = new LinkedHashMap<>();
Map<String, Integer> treeMap = new TreeMap<>();

// Insert in this order: C, A, B
for (var m : List.of(hashMap, linkedMap, treeMap)) {
    m.put("CUR3001", 3); m.put("SAV2001", 1); m.put("FD4001", 2);
}

hashMap.keySet();   // [SAV2001, FD4001, CUR3001] — RANDOM order (hash-based)
linkedMap.keySet(); // [CUR3001, SAV2001, FD4001] — INSERTION order!
treeMap.keySet();   // [CUR3001, FD4001, SAV2001] — SORTED order (alphabetical)!

// ═══ PERFORMANCE ═══
// HashMap:       get/put O(1)      — fastest
// LinkedHashMap: get/put O(1)      — slight overhead (maintain linked list)
// TreeMap:       get/put O(log n)  — slowest (tree balancing)
// Memory: HashMap < LinkedHashMap < TreeMap

// ═══ LinkedHashMap: ACCESS ORDER (LRU cache!) ═══
// Constructor: LinkedHashMap(capacity, loadFactor, accessOrder=true)
Map<String, String> lruCache = new LinkedHashMap<>(16, 0.75f, true) {
    @Override
    protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
        return size() > 3;  // evict oldest when size > 3
    }
};
lruCache.put("A", "1"); lruCache.put("B", "2"); lruCache.put("C", "3");
// Order: A → B → C
lruCache.get("A");  // access A → moves to tail!
// Order: B → C → A
lruCache.put("D", "4");  // size > 3 → evict B (eldest)!
// Order: C → A → D

// ═══ TreeMap: NavigableMap operations ═══
TreeMap<String, BigDecimal> sortedBalances = new TreeMap<>();
sortedBalances.put("SAV2001", new BigDecimal("75000"));
sortedBalances.put("CUR3001", new BigDecimal("120000"));
sortedBalances.put("FD4001", new BigDecimal("500000"));

sortedBalances.firstKey();                  // "CUR3001" (smallest)
sortedBalances.lastKey();                   // "SAV2001" (largest)
sortedBalances.floorKey("EEE");             // "CUR3001" (≤ EEE)
sortedBalances.ceilingKey("EEE");           // "FD4001" (≥ EEE)
sortedBalances.subMap("CUR3001", "SAV2001");// CUR3001, FD4001 (range view)
