package com.bank.mapcompare;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class MapOrderingTest {

    // ═══ HashMap: no ordering guarantee ═══
    @Test
    void hashMap_unordered() {
        Map<String, Integer> map = new HashMap<>();
        map.put("CUR3001", 3);
        map.put("SAV2001", 1);
        map.put("FD4001", 2);
        // Order is NOT guaranteed — depends on hash values
        assertThat(map).hasSize(3);
    }

    // ═══ LinkedHashMap: insertion order ═══
    @Test
    void linkedHashMap_insertionOrder() {
        Map<String, Integer> map = new LinkedHashMap<>();
        map.put("CUR3001", 3);
        map.put("SAV2001", 1);
        map.put("FD4001", 2);
        assertThat(new ArrayList<>(map.keySet()))
            .containsExactly("CUR3001", "SAV2001", "FD4001");  // insertion order!
    }

    // ═══ TreeMap: sorted order ═══
    @Test
    void treeMap_sortedOrder() {
        Map<String, Integer> map = new TreeMap<>();
        map.put("CUR3001", 3);
        map.put("SAV2001", 1);
        map.put("FD4001", 2);
        assertThat(new ArrayList<>(map.keySet()))
            .containsExactly("CUR3001", "FD4001", "SAV2001");  // alphabetical!
    }

    // ═══ LinkedHashMap: access order (LRU) ═══
    @Test
    void linkedHashMap_accessOrder_LRU() {
        LinkedHashMap<String, String> lru = new LinkedHashMap<>(16, 0.75f, true);
        lru.put("A", "1");
        lru.put("B", "2");
        lru.put("C", "3");
        // Order: A, B, C

        lru.get("A");  // access A → moves to end!
        assertThat(new ArrayList<>(lru.keySet()))
            .containsExactly("B", "C", "A");  // A moved to tail!
    }

    // ═══ LRU Cache with eviction ═══
    @Test
    void lruCache_evictsOldest() {
        LinkedHashMap<String, String> cache = new LinkedHashMap<>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                return size() > 3;
            }
        };

        cache.put("A", "1"); cache.put("B", "2"); cache.put("C", "3");
        assertThat(cache).hasSize(3);

        cache.put("D", "4");  // size > 3 → evict eldest (A)!
        assertThat(cache).hasSize(3);
        assertThat(cache.containsKey("A")).isFalse();  // evicted!
        assertThat(cache.containsKey("D")).isTrue();
    }

    // ═══ TreeMap: NavigableMap operations ═══
    @Test
    void treeMap_navigable() {
        TreeMap<String, Integer> map = new TreeMap<>();
        map.put("SAV2001", 1); map.put("CUR3001", 3); map.put("FD4001", 2);

        assertThat(map.firstKey()).isEqualTo("CUR3001");
        assertThat(map.lastKey()).isEqualTo("SAV2001");
        assertThat(map.floorKey("EEE")).isEqualTo("CUR3001");    // ≤ EEE
        assertThat(map.ceilingKey("EEE")).isEqualTo("FD4001");   // ≥ EEE
        assertThat(map.subMap("CUR3001", "SAV2001").keySet())
            .containsExactly("CUR3001", "FD4001");  // range [CUR, SAV)
    }

    // ═══ Convert LinkedHashMap → TreeMap for sorted output ═══
    @Test
    void convertToSorted() {
        LinkedHashMap<String, Integer> cache = new LinkedHashMap<>();
        cache.put("CUR3001", 3); cache.put("SAV2001", 1); cache.put("FD4001", 2);

        TreeMap<String, Integer> sorted = new TreeMap<>(cache);
        assertThat(new ArrayList<>(sorted.keySet()))
            .containsExactly("CUR3001", "FD4001", "SAV2001");
    }
}
